        AddressResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);

        // 2. Order 생성
        Order order = Order.builder()
                .user(buyer)
                .totalAmount(saleBid.getBidPrice())
                .status(OrderStatus.PENDING_PAYMENT)
                .build();

